// ============================================================
// STANDARDIZE & CLEAN PAYLOAD
// ============================================================
// Enforces strict schema, cleans addresses, maps status,
// generates unique_id for deduplication.
// ============================================================

return items.map(item => {
  const d = item.json;

  // --- Clean Property Address ---
  let address = d.property_address || 'N/A';
  const isWithdrawn = /\*{3}Withdrawn\*{3}/i.test(address);
  address = address.replace(/\*{3}Withdrawn\*{3}/gi, '').trim();
  // Strip leading county prefix: "Clark County, WA: APN: 97978298" → "APN: 97978298"
  const countyPrefixMatch = address.match(/^[^:]+County,?\s*[A-Z]{2}\s*:\s*(.+)$/i);
  if (countyPrefixMatch) {
    address = countyPrefixMatch[1].trim();
  }

  // --- Map Status ---
  let status = 'Active';
  const rawStatus = (d.status || '').toLowerCase();
  const rawRemaining = (d.time_remaining || '').toLowerCase();

  if (isWithdrawn || rawStatus === 'withdrawn') {
    status = 'Withdrawn';
  } else if (rawRemaining === 'sold' || rawStatus === 'sold') {
    status = 'Sold';
  } else if (rawRemaining === 'closed' || rawStatus === 'closed') {
    status = 'Closed';
  } else if (rawStatus === 'upcoming' || rawStatus === 'preview') {
    status = 'Upcoming';
  } else {
    status = 'Active';
  }

  // --- Source ---
  const source = d.source || 'Unknown';

  // --- County & State ---
  const county = d.county || 'N/A';
  const state = d.state || '';

  // --- Generate unique ID for deduplication ---
  const uniqueId = `${source}|${county}|${address}`.toLowerCase().replace(/\s+/g, '');

  // --- Current Bid ---
  let bid = 0;
  if (typeof d.current_bid === 'number') {
    bid = d.current_bid;
  } else if (d.current_bid) {
    bid = parseFloat(String(d.current_bid).replace(/[^\d.]/g, '')) || 0;
  }

  // --- Auction URL ---
  const auctionUrl = d.auction_url || '';

  return {
    json: {
      property_address: address,
      county: county,
      state: state,
      source: source,
      status: status,
      current_bid: bid,
      bidding_date: d.bidding_date || '',
      bidding_time: d.bidding_time || '',
      sale_date: d.sale_date || '',
      auction_url: auctionUrl,
      unique_id: uniqueId
    }
  };
});

// ============================================================
// DEDUPLICATION + ROUTE: New vs Update vs Skip
// ============================================================

// Build map of existing entries from Notion
// Pagination returns one item per page - flatten every page or the
// dedup map silently only covers the first 100 rows.
const pages = $('Fetch Existing Entries').all();
const existingResults = pages.flatMap(p => p.json.results || []);
const existingMap = new Map();

for (const page of existingResults) {
  const props = page.properties || {};
  let uniqueId = '';

  if (props['Unique ID']?.rich_text?.[0]?.plain_text) {
    uniqueId = props['Unique ID'].rich_text[0].plain_text;
  }

  if (uniqueId) {
    existingMap.set(uniqueId, {
      pageId: page.id,
      currentBid: props['Current Bid']?.number || 0,
      status: props['Status']?.select?.name || ''
    });
  }
}

// Process incoming items
const incomingItems = $('Standardize Payload').all();
const newItems = [];
const updateItems = [];
let skipped = 0;

for (const item of incomingItems) {
  const uid = item.json.unique_id;
  const existing = existingMap.get(uid);

  if (!existing) {
    // New entry → create
    newItems.push(item);
  } else if (
    existing.currentBid !== item.json.current_bid ||
    existing.status !== item.json.status
  ) {
    // Bid or status changed → update
    updateItems.push({
      json: {
        ...item.json,
        notion_page_id: existing.pageId
      }
    });
  } else {
    skipped++;
  }
}

console.log(`📊 Dedup: ${existingResults.length} existing across ${pages.length} page(s), ${incomingItems.length} incoming, ${newItems.length} new, ${updateItems.length} updates, ${skipped} skipped`);

// Output 1: new items, Output 2: updates
return [
  newItems.length > 0 ? newItems : [{ json: { _skip: true } }],
  updateItems.length > 0 ? updateItems : [{ json: { _skip: true } }]
];
